function auftragZugangId(text){const t=String(text||'').toLowerCase();if(!t)return '';if(/kind|selbst/.test(t))return 'schueler_selbst';if(/sorgeber|eltern|mutter|vater/.test(t))return 'eltern';if(/klassenleit|lehrkr|lehrer/.test(t))return 'lehrkraft';if(/schulleit/.test(t))return 'schulleitung';if(/mitschül/.test(t))return 'mitschueler';if(/anfrage|portal/.test(t))return 'anfrageportal';if(/jugendamt|extern|andere/.test(t))return 'extern';return '';}
