function dossierTypeOptions(selected){const basis=dossierTypes.filter(v=>v!=='Gruppengespräch'||selected==='Gruppengespräch');const list=!selected||basis.includes(selected)?basis:[selected,...basis];return list.map(v=>`<option value="${DE(v)}" ${v===selected?'selected':''}>${DE(v==='zusätzliche Information'?'Zusätzliche Information':v)}</option>`).join('');}
