function dossierAutoTitle(text){const line=String(text||'').split(/\r?\n/).map(s=>s.trim()).find(Boolean)||'';const first=line.split(/(?<=[.!?])\s/)[0]||line;if(first.length<=70)return first.replace(/[.:;,]$/,'');const cut=first.slice(0,70),at=cut.lastIndexOf(' ');return (at>30?cut.slice(0,at):cut).replace(/[.:;,]$/,'')+' …';}
