 const pupils=active.map(s=>({givenId:s.id,first:s.first,last:s.last,className:Dossier.nextClass(s.className)||s.className,schoolYear:next}));
 dossierMakePreview(pupils,next,classLeads);
 for(const r of pendingYearChange.rows){const old=data.students.find(s=>s.id===r.studentId),target=Dossier.nextClass(old?.className||'');r.confirmed=false;r.graduating=!target;r.reason=target?'Reguläre Versetzung':'Abschlussjahrgang – Abgang / Wechsel prüfen';}
