/* Ausbau Arbeitskorb und Qualitätsfluss */
function dossierWorkItems(){
 const result={overdue:[],today:[],responses:[],signals:[],suggestions:[],documents:[],withoutNext:[]};
 const seen={};
 for(const s of data.students.filter(x=>x.active!==false)){
  let events=[];try{events=Dossier.timeline(data,s.id,legacyStudentEvents(s.id));}catch{}
  const tasks=Dossier.work(data,s.id);
  for(const t of tasks.filter(t=>!t.done)){const item={kind:'task',studentId:s.id,title:t.title,meta:(t.due?t.due+' · ':'')+(t.assignedTo||'Zuständigkeit prüfen'),id:t.id};if(t.due&&t.due<today())result.overdue.push(item);if(t.due===today())result.today.push(item);if(String(t.status||'').toLowerCase().includes('rückmeldung'))result.responses.push(item);}
  for(const e of events){
   if(e.planned&&e.plannedDate&&e.plannedDate>=today())result.today.push({kind:'event',studentId:s.id,title:e.title||e.eventKind,meta:'Geplant · '+e.plannedDate,key:e.key});
   if(e.status&&/rückmeldung ausstehend|offen|prüfen/i.test(String(e.status)))result.responses.push({kind:'event',studentId:s.id,title:e.title||e.eventKind,meta:String(e.status),key:e.key});
   for(const sug of (e.actionSuggestions||[]).filter(x=>x.status==='offen'))result.suggestions.push({kind:'suggestion',studentId:s.id,title:sug.title,meta:'Vorschlag prüfen',key:e.key});
   const hasNext=data.tasks.some(t=>t.sourceEntryKey===e.key)||data.journal.some(x=>x.sourceEntryKey===e.key)||e.result||e.agreement;
   if(e.key&&e.type!=='Dokument'&&!e.generalInfo&&!e.planned&&!hasNext)result.withoutNext.push({kind:'event',studentId:s.id,title:e.title||e.eventKind,meta:'Kein nächster Schritt',key:e.key});
  }
 }
 for(const d of (data.documentEvents||[])){const events=d.studentId?Dossier.timeline(data,d.studentId,legacyStudentEvents(d.studentId)):[];if(!d.sourceEntryKey||!events.some(e=>e.key===d.sourceEntryKey))result.documents.push({kind:'document',studentId:d.studentId,title:d.name||'Dokument',meta:'Chronikzuordnung fehlt',id:d.attachmentId});}
 return result;
}
